import assert from "node:assert/strict";
import { test } from "node:test";
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

import { treeSets, brokenLinksIn, checkRepo } from "./link-check.mjs";

const tree = treeSets([
  "README.md",
  "AGENTS.md",
  "docs/USAGE.md",
  "docs/adr/0001-a.md",
  "crates/core/src/graph/mod.rs",
  "editors/vscode/media/mindleak_logo.png",
  "gaps.d/note.md",
]);

test("a link to an existing file is not broken", () => {
  const broken = brokenLinksIn(
    "README.md",
    "See [usage](docs/USAGE.md).",
    tree,
  );
  assert.equal(broken.length, 0);
});

test("a link to an existing directory is not broken", () => {
  const broken = brokenLinksIn(
    "DEVELOPERS.md",
    "The [gaps](gaps.d/) live here.",
    tree,
  );
  assert.equal(broken.length, 0);
});

test("a link to a missing file is broken, and names its location", () => {
  const broken = brokenLinksIn(
    "docs/USAGE.md",
    "gone: [x](../crates/core/src/graph.rs)",
    tree,
  );
  assert.equal(broken.length, 1);
  assert.equal(broken[0].file, "docs/USAGE.md");
  assert.equal(broken[0].line, 1);
  assert.match(broken[0].target, /graph\.rs/);
});

test("a link inside an inline code span is an example, not a broken link", () => {
  // The exact case that blocked #234: an illustrative rename written as a link.
  const broken = brokenLinksIn(
    "changelog.d/x.md",
    "Renaming orphaned every `[ADR-00NN](00NN-old-slug.md)` inbound link.",
    tree,
  );
  assert.equal(broken.length, 0);
});

test("a real link outside the code span on the same line is still checked", () => {
  const broken = brokenLinksIn(
    "docs/USAGE.md",
    "example `[x](00NN-old-slug.md)`, but see [gone](missing-file.md) too",
    tree,
  );
  assert.equal(broken.length, 1);
  assert.match(broken[0].target, /missing-file\.md/);
});

test("a link inside a fenced code block is skipped", () => {
  const broken = brokenLinksIn(
    "docs/USAGE.md",
    ["Example:", "```md", "[x](does-not-exist.md)", "```", "done"].join("\n"),
    tree,
  );
  assert.equal(broken.length, 0);
});

test("a broken link after a closed fence is still caught", () => {
  const broken = brokenLinksIn(
    "docs/USAGE.md",
    ["```", "[x](in-fence.md)", "```", "[y](out-of-fence.md)"].join("\n"),
    tree,
  );
  assert.equal(broken.length, 1);
  assert.match(broken[0].target, /out-of-fence\.md/);
});

test("a root-relative target that exists from the repo root is accepted", () => {
  // From docs/USAGE.md this does not resolve file-relative, but the repo mixes
  // conventions and it resolves from root; flagging that would be noise.
  const broken = brokenLinksIn(
    "docs/USAGE.md",
    "[facade](crates/core/src/graph/mod.rs)",
    tree,
  );
  assert.equal(broken.length, 0);
});

test("a #anchor is stripped before the path is resolved", () => {
  const ok = brokenLinksIn("README.md", "[a](docs/USAGE.md#section)", tree);
  assert.equal(ok.length, 0);
  const bad = brokenLinksIn("README.md", "[a](docs/MISSING.md#section)", tree);
  assert.equal(bad.length, 1);
});

test("external, pure-anchor and placeholder links are not checked", () => {
  const text = [
    "[web](https://example.com)",
    "[mail](mailto:x@example.com)",
    "[top](#heading)",
    "[tpl](docs/${name}.md)",
    "[ellipsis](...)",
    "[cmd](a file with spaces.md)",
  ].join("\n");
  assert.equal(brokenLinksIn("README.md", text, tree).length, 0);
});

test("a pending screenshot image is exempt even when the file is absent", () => {
  const text = "![hero](editors/vscode/media/screenshots/overview.png)";
  assert.equal(brokenLinksIn("editors/vscode/README.md", text, tree).length, 0);
});

test("treeSets derives every ancestor directory of a tracked file", () => {
  const { dirSet } = tree;
  assert.ok(dirSet.has("crates/core/src/graph"));
  assert.ok(dirSet.has("crates"));
  assert.ok(dirSet.has("docs/adr"));
});

test("a tracked document deleted from the working tree is absent", () => {
  const root = mkdtempSync(path.join(tmpdir(), "mindleak-link-check-"));
  try {
    writeFileSync(path.join(root, "deleted.md"), "# Gone\n");
    writeFileSync(
      path.join(root, "living.md"),
      "[deleted](deleted.md)\n[missing](missing.md)\n",
    );
    execFileSync("git", ["init", "--quiet"], { cwd: root });
    execFileSync("git", ["add", "deleted.md", "living.md"], { cwd: root });
    rmSync(path.join(root, "deleted.md"));

    const broken = checkRepo(root);

    assert.deepEqual(
      broken.map(({ file, target }) => ({ file, target })),
      [
        { file: "living.md", target: "deleted.md" },
        { file: "living.md", target: "missing.md" },
      ],
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

// The guard, live: this runs from pre-push via script-tests, so a document that
// starts pointing at a moved or deleted file fails the push rather than rotting
// unnoticed. `docs/adr/` is in scope too (see link-check.mjs).
test("the repository's own docs have no broken links", () => {
  const root = execFileSync("git", ["rev-parse", "--show-toplevel"], {
    encoding: "utf8",
  }).trim();
  const broken = checkRepo(root);
  assert.deepEqual(
    broken,
    [],
    `broken relative links in living docs:\n${broken
      .map((b) => `  ${b.file}:${b.line} -> ${b.target}`)
      .join("\n")}`,
  );
});

// Regression: an ADR cited a `gaps.d/` fragment, the fragment was deleted once
// its defect was fixed — which is what the process asks for — and nothing
// noticed. `adr-link-check.mjs` matches only sibling `NNNN-slug.md` targets, and
// this tool skipped `docs/adr/` wholesale, so the citation dangled in a record
// nobody re-reads. Fails against the excluded version: it reported nothing.
test("an ADR citing a deleted gaps.d fragment is caught", () => {
  const root = mkdtempSync(path.join(tmpdir(), "mindleak-adr-link-"));
  try {
    mkdirSync(path.join(root, "docs", "adr"), { recursive: true });
    mkdirSync(path.join(root, "gaps.d"), { recursive: true });
    writeFileSync(path.join(root, "gaps.d", "note.md"), "- **A gap.**\n");
    writeFileSync(
      path.join(root, "docs", "adr", "0092-x.md"),
      "Recorded in [note](../../gaps.d/note.md).\n",
    );
    execFileSync("git", ["init", "--quiet"], { cwd: root });
    execFileSync("git", ["add", "."], { cwd: root });
    rmSync(path.join(root, "gaps.d", "note.md"));

    const broken = checkRepo(root);

    assert.deepEqual(
      broken.map(({ file, target }) => ({ file, target })),
      [{ file: "docs/adr/0092-x.md", target: "../../gaps.d/note.md" }],
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
